   >>> GenerateCloseFriendString("1234")
   "cege"

*/
    static string GenerateCloseFriendString(string inputString)

source_record.canonical_solution:
{
    if (inputString.Length < 2 || inputString.Length > 100)
    {
        throw new ArgumentException("Input string length should be between 2 and 100 characters.");
    }

    StringBuilder closeFriendString = new StringBuilder();

    for (int i = 0; i < inputString.Length; i++)
    {
        int asciiValue = (int)inputString[i];
        if (asciiValue > 63)
        {
            throw new ArgumentException("Each character's ASCII value should not exceed 63.");
        }

        int nextAsciiValue = (i == inputString.Length - 1) ? (int)inputString[0] : (int)inputString[i + 1];
