{
    oneDollarTotal = oneDollarKids;
    twoDollarTotal = twoDollarKids;
    permutations = Factorial(oneDollarKids) * Factorial(twoDollarKids);
    arrangements = 0;

    CountArrangements(totalKids, oneDollarKids, twoDollarKids);
    return arrangements;
}

static int arrangements = 0, oneDollarTotal, twoDollarTotal, permutations;



static void CountArrangements(int n, int oneDollarRemaining, int twoDollarRemaining)
{
    // Check if the arrangement is invalid
    if ((oneDollarTotal - oneDollarRemaining) < (twoDollarTotal - twoDollarRemaining))
        return;

    // If no kids are left, add the number of permutations to arrangements
    if (n == 0)
    {
        arrangements += permutations;
        return;
    }

    // Choose a one-dollar kid
    if (oneDollarRemaining > 0)
        CountArrangements(n - 1, oneDollarRemaining - 1, twoDollarRemaining);

    // Choose a two-dollar kid
    if (twoDollarRemaining > 0)
        CountArrangements(n - 1, oneDollarRemaining, twoDollarRemaining - 1);
}


static int Factorial(int number)
{
    int result = 1;
    for (int i = 2; i <= number; i++)
        result *= i;
    return result;
}

