using System;
using System.Collections.Generic;
using System.Diagnostics;

class Program
{



    static (int, int, int) CountCharacters(string s)
    {
        int digitCount = 0, lowerCaseCount = 0, upperCaseCount = 0;
        foreach (char c in s)
        {
            if (char.IsDigit(c)) digitCount++;
            else if (char.IsLower(c)) lowerCaseCount++;
            else if (char.IsUpper(c)) upperCaseCount++;
        }
        return (digitCount, lowerCaseCount, upperCaseCount);
    }
